// import logo from './logo.svg';
import './App.css';
import PostComponenet from './js/PostComponenet.js'
import SideButtons from './js/SideButtons.js';

function App() {
  const RepeatedNo = 4 
  const Componenets = []
  for (let i = 0; i<RepeatedNo; i++) {
    Componenets.push(<PostComponenet key={i} />)
  }

  const names = ["Abdo", "Hamid", "Mosa", "Ali"]
  const NamesReuseable = names.map((name, index) => <PostComponenet name={name} />)

  const fruits = [
    { id: 1, name: 'Apple' },
    { id: 2, name: 'Banana' },
    { id: 3, name: 'Cherry' },
  ];
  const fruitList = fruits.map((fruits) => <li key={fruits.id}>{fruits.name}</li>)


  return (
    <div className="App">
      <header className="App-header">
        <h1>This is the first component lesson for Abu Omair</h1>
          </header>

          <div style = {{display: 'flex', justifyContent: 'center', alignItems: 'center', marginLeft: '20%', marginRight: '20%'}}>
          {/* This is the bodey start */}
          <div className="main-content" style = {{display: 'flex', justifyContent: 'center'}}>
            {/* This is the components start */}
            <div className='left-side'>
             {NamesReuseable}

             <ul>
        {fruits.map((fruit) => (
          <li key={fruit.id}>
            {fruit.name}
          </li>
        ))}
      </ul>
              {/* {Componenets}
              <PostComponenet name="Abdo"/>
              <PostComponenet name='Hamid'/>
              <PostComponenet name='Mosa'/>
              <PostComponenet name="Ali"/> */}
            </div>
            {/* == This is the components end == */}

            {/* This is the Side Buttons start */}
            <div className='right-side'>
              <SideButtons />
            </div>
            {/* == This is the Side Buttons end == */}
          </div>
          {/* == This is the bodey end == */}
          </div>
    </div>
  );
}

export default App;
